from __future__ import annotations

import shutil
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CHECKOUT = ROOT / "src" / "app" / "checkout" / "page.tsx"
INVOICE = ROOT / "src" / "lib" / "customerInvoice.ts"
BACKUP = ROOT / "work" / "order-invoice-backups" / datetime.now().strftime("%Y%m%d-%H%M%S")

CHECKOUT_CONTENT = '"use client";\n\nimport Link from "next/link";\nimport { MessageCircle, FileText } from "lucide-react";\nimport { useState } from "react";\nimport { orderConfig } from "@/lib/orderConfig";\nimport { useCartStore } from "@/lib/store";\nimport { formatPrice } from "@/lib/utils";\nimport {\n  buildWhatsAppMessage,\n  getInvoiceNumber,\n  printCustomerInvoice,\n  type CustomerDetails,\n} from "@/lib/customerInvoice";\n\nconst initialCustomer: CustomerDetails = {\n  name: "",\n  phone: "",\n  email: "",\n  address: "",\n  city: "",\n  state: "",\n  pincode: "",\n};\n\nexport default function CheckoutPage() {\n  const { items } = useCartStore();\n  const [customer, setCustomer] = useState<CustomerDetails>(initialCustomer);\n  const [error, setError] = useState("");\n\n  const total = items.reduce(\n    (sum, item) =>\n      sum + (item.type === "combo" ? item.comboPrice ?? 0 : item.referencePrice ?? 0),\n    0,\n  );\n\n  function update(field: keyof CustomerDetails, value: string) {\n    setCustomer((current) => ({ ...current, [field]: value }));\n  }\n\n  function validate() {\n    const required: Array<keyof CustomerDetails> = [\n      "name", "phone", "email", "address", "city", "state", "pincode",\n    ];\n    if (required.some((field) => !customer[field].trim())) {\n      setError("Please fill all required customer details.");\n      return false;\n    }\n    if (!/^\\S+@\\S+\\.\\S+$/.test(customer.email)) {\n      setError("Please enter a valid email address.");\n      return false;\n    }\n    if (!/^\\d{10}$/.test(customer.phone.replace(/\\D/g, ""))) {\n      setError("Please enter a valid 10-digit mobile number.");\n      return false;\n    }\n    if (!/^\\d{6}$/.test(customer.pincode.trim())) {\n      setError("Please enter a valid 6-digit pincode.");\n      return false;\n    }\n    setError("");\n    return true;\n  }\n\n  function placeOrder() {\n    if (!validate() || items.length === 0) return;\n\n    const invoiceNumber = getInvoiceNumber();\n\n    try {\n      printCustomerInvoice(customer, items, invoiceNumber);\n\n      const orderText = buildWhatsAppMessage(customer, items, invoiceNumber);\n      const whatsappUrl =\n        `https://wa.me/${orderConfig.whatsappNumber}?text=${encodeURIComponent(orderText)}`;\n\n      window.setTimeout(() => {\n        window.open(whatsappUrl, "_blank", "noopener,noreferrer");\n      }, 300);\n    } catch (err) {\n      setError(err instanceof Error ? err.message : "Could not generate invoice.");\n    }\n  }\n\n  return (\n    <div className="min-h-screen bg-stone-50 px-4 py-12">\n      <div className="mx-auto max-w-6xl">\n        <div className="mb-8 text-center">\n          <p className="text-sm font-semibold uppercase tracking-[0.14em] text-[#bf4800]">\n            Checkout\n          </p>\n          <h1 className="mt-2 text-4xl font-semibold text-stone-900">\n            Customer & order details\n          </h1>\n          <p className="mt-3 text-stone-500">\n            Enter your details, generate the invoice, then continue to WhatsApp.\n          </p>\n        </div>\n\n        {items.length === 0 ? (\n          <div className="mx-auto max-w-xl rounded-[28px] border border-stone-200 bg-white p-8 text-center shadow-sm">\n            <MessageCircle size={50} className="mx-auto mb-5 text-amber-600" />\n            <h2 className="mb-2 text-2xl font-bold text-stone-800">Your cart is empty</h2>\n            <p className="mb-6 text-stone-500">Add a perfume or build a combo first.</p>\n            <Link\n              href="/shop"\n              className="inline-flex rounded-full bg-amber-600 px-6 py-3 text-sm font-semibold text-white"\n            >\n              Shop fragrances\n            </Link>\n          </div>\n        ) : (\n          <div className="grid gap-6 lg:grid-cols-[1.15fr_0.85fr]">\n            <section className="rounded-[28px] border border-stone-200 bg-white p-6 shadow-sm">\n              <div className="mb-6 flex items-center gap-3">\n                <FileText className="text-amber-600" />\n                <div>\n                  <h2 className="text-xl font-semibold text-stone-900">Customer details</h2>\n                  <p className="text-sm text-stone-500">All fields are required.</p>\n                </div>\n              </div>\n\n              <div className="grid gap-4 sm:grid-cols-2">\n                <Field label="Full Name *" value={customer.name} onChange={(v) => update("name", v)} />\n                <Field label="Mobile Number *" value={customer.phone} onChange={(v) => update("phone", v)} inputMode="numeric" />\n                <Field label="Email *" value={customer.email} onChange={(v) => update("email", v)} type="email" />\n                <Field label="Pincode *" value={customer.pincode} onChange={(v) => update("pincode", v)} inputMode="numeric" />\n                <div className="sm:col-span-2">\n                  <Field label="Complete Address *" value={customer.address} onChange={(v) => update("address", v)} />\n                </div>\n                <Field label="City *" value={customer.city} onChange={(v) => update("city", v)} />\n                <Field label="State *" value={customer.state} onChange={(v) => update("state", v)} />\n              </div>\n\n              {error ? (\n                <div className="mt-5 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">\n                  {error}\n                </div>\n              ) : null}\n\n              <button\n                type="button"\n                onClick={placeOrder}\n                className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-full bg-[#0071e3] px-6 py-4 text-sm font-bold text-white transition hover:bg-[#0067d3]"\n              >\n                <MessageCircle size={18} />\n                Generate Invoice & Order on WhatsApp\n              </button>\n\n              <p className="mt-3 text-center text-xs text-stone-500">\n                Invoice opens in a new window. Use “Print / Save as PDF” there.\n              </p>\n            </section>\n\n            <aside className="h-fit rounded-[28px] border border-stone-200 bg-white p-6 shadow-sm lg:sticky lg:top-6">\n              <h2 className="text-xl font-semibold text-stone-900">Order summary</h2>\n              <div className="mt-5 space-y-4">\n                {items.map((item) => (\n                  <div key={item.id} className="border-b border-stone-100 pb-4">\n                    <div className="flex justify-between gap-3">\n                      <span className="font-medium text-stone-800">\n                        {item.type === "combo" ? item.comboName : item.productName}\n                      </span>\n                      <span className="font-semibold text-stone-900">\n                        {formatPrice(item.type === "combo" ? item.comboPrice ?? 0 : item.referencePrice ?? 0)}\n                      </span>\n                    </div>\n                    {item.type === "combo" ? (\n                      <p className="mt-1 text-xs text-stone-500">\n                        {item.quantity ?? 0} × {item.bottleSize ?? 0}ml\n                      </p>\n                    ) : null}\n                  </div>\n                ))}\n              </div>\n              <div className="mt-5 flex items-center justify-between border-t border-stone-200 pt-5">\n                <span className="text-lg font-semibold text-stone-800">Total</span>\n                <span className="text-2xl font-bold text-stone-900">{formatPrice(total)}</span>\n              </div>\n            </aside>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n\nfunction Field({\n  label,\n  value,\n  onChange,\n  type = "text",\n  inputMode,\n}: {\n  label: string;\n  value: string;\n  onChange: (value: string) => void;\n  type?: string;\n  inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"];\n}) {\n  return (\n    <label className="block">\n      <span className="mb-2 block text-sm font-semibold text-stone-700">{label}</span>\n      <input\n        type={type}\n        value={value}\n        inputMode={inputMode}\n        onChange={(e) => onChange(e.target.value)}\n        className="w-full rounded-2xl border border-stone-200 bg-white px-4 py-3 text-sm text-stone-900 outline-none transition focus:border-amber-500 focus:ring-2 focus:ring-amber-100"\n      />\n    </label>\n  );\n}\n'
INVOICE_CONTENT = 'import type { CartItem } from "@/lib/store";\nimport { formatPrice } from "@/lib/utils";\n\nexport type CustomerDetails = {\n  name: string;\n  phone: string;\n  email: string;\n  address: string;\n  city: string;\n  state: string;\n  pincode: string;\n};\n\nfunction money(value: number) {\n  return formatPrice(Math.round(value));\n}\n\nfunction esc(value: string) {\n  return value\n    .replace(/&/g, "&amp;")\n    .replace(/</g, "&lt;")\n    .replace(/>/g, "&gt;")\n    .replace(/"/g, "&quot;")\n    .replace(/\'/g, "&#039;");\n}\n\nexport function getInvoiceNumber() {\n  const key = "sfh-invoice-sequence";\n  const now = new Date();\n  const date = `${String(now.getDate()).padStart(2, "0")}${String(now.getMonth() + 1).padStart(2, "0")}${now.getFullYear()}`;\n  const next = Number(window.localStorage.getItem(key) || "0") + 1;\n  window.localStorage.setItem(key, String(next));\n  return `SFH-${date}-${String(next).padStart(2, "0")}`;\n}\n\nexport function buildWhatsAppMessage(\n  customer: CustomerDetails,\n  items: CartItem[],\n  invoiceNumber: string,\n) {\n  const lines = [\n    "Hello! I would like to place my order on WhatsApp.",\n    "",\n    `Invoice Number: ${invoiceNumber}`,\n    "",\n    "CUSTOMER DETAILS",\n    `Name: ${customer.name}`,\n    `Mobile: ${customer.phone}`,\n    `Email: ${customer.email}`,\n    `Address: ${customer.address}, ${customer.city}, ${customer.state} - ${customer.pincode}`,\n    "",\n    "ORDER DETAILS",\n  ];\n\n  for (const item of items) {\n    if (item.type === "combo") {\n      lines.push(\n        `Combo: ${item.comboName ?? "Custom Combo"}`,\n        `Bottle Size: ${item.bottleSize ?? "-"}ml`,\n        `Quantity: ${item.quantity ?? item.selectedProductIds?.length ?? 0}`,\n        `Selected Perfumes: ${(item.selectedProductNames ?? []).join(", ") || "None"}`,\n        `Reference Price: ${money(item.referencePrice ?? 0)}`,\n        `Combo Price: ${money(item.comboPrice ?? 0)}`,\n        `You Save: ${money(item.savings ?? 0)}`,\n        "",\n      );\n    } else {\n      lines.push(\n        `Product: ${item.productName ?? "Perfume"}`,\n        `Price: ${money(item.referencePrice ?? 0)}`,\n        "",\n      );\n    }\n  }\n\n  const total = items.reduce(\n    (sum, item) =>\n      sum + (item.type === "combo" ? item.comboPrice ?? 0 : item.referencePrice ?? 0),\n    0,\n  );\n\n  lines.push(`ORDER TOTAL: ${money(total)}`, "", "Please confirm my order and share the payment details.", "Thank you!");\n  return lines.join("\\n");\n}\n\nexport function printCustomerInvoice(\n  customer: CustomerDetails,\n  items: CartItem[],\n  invoiceNumber: string,\n) {\n  const date = new Date().toLocaleDateString("en-IN");\n\n  const rows = items.map((item) => {\n    const combo = item.type === "combo";\n    const name = combo ? item.comboName ?? "Custom Combo" : item.productName ?? "Perfume";\n    const details = combo ? `${item.quantity ?? 0} × ${item.bottleSize ?? 0}ml` : "Single perfume";\n    const price = combo ? item.comboPrice ?? 0 : item.referencePrice ?? 0;\n    const savings = combo ? item.savings ?? 0 : 0;\n\n    return `<tr>\n      <td><strong>${esc(name)}</strong><div class="muted">${esc(details)}</div>\n      ${combo ? `<div class="muted">Selected: ${esc((item.selectedProductNames ?? []).join(", "))}</div>` : ""}</td>\n      <td class="right">${money(price)}</td>\n      <td class="right">${savings ? `-${money(savings)}` : money(0)}</td>\n    </tr>`;\n  }).join("");\n\n  const total = items.reduce(\n    (sum, item) =>\n      sum + (item.type === "combo" ? item.comboPrice ?? 0 : item.referencePrice ?? 0),\n    0,\n  );\n\n  const html = `<!doctype html><html><head><meta charset="utf-8">\n  <title>${esc(invoiceNumber)} - Smells From Heaven</title>\n  <style>\n  *{box-sizing:border-box}body{margin:0;padding:32px;background:#f5f5f0;color:#1f1f1f;font-family:Arial,sans-serif}\n  .invoice{max-width:850px;margin:auto;background:#fff;border:1px solid #e5e0d8;border-radius:22px;overflow:hidden}\n  .header{padding:30px;background:#171717;color:#fff}.brand{font-size:26px;font-weight:800}.tag{margin-top:6px;color:#f2c38b}\n  .content{padding:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:26px}\n  .box{border:1px solid #e7e2db;border-radius:14px;padding:16px}h2{font-size:15px;margin:0 0 10px;text-transform:uppercase;letter-spacing:.08em}\n  p{margin:5px 0}.muted{color:#777;font-size:13px;margin-top:5px;line-height:1.45}table{width:100%;border-collapse:collapse}\n  th,td{padding:14px 8px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#777}\n  .right{text-align:right}.total{font-size:22px;font-weight:800}.actions{max-width:850px;margin:16px auto;text-align:right}\n  button{border:0;border-radius:999px;padding:12px 20px;background:#0071e3;color:#fff;font-weight:700;cursor:pointer}\n  @media print{body{padding:0;background:#fff}.invoice{border:0;border-radius:0}.actions{display:none}}\n  @media(max-width:650px){.grid{grid-template-columns:1fr}}\n  </style></head><body>\n  <div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div>\n  <div class="invoice"><div class="header"><div class="brand">Smells From Heaven</div>\n  <div class="tag">Where Every Smell Is A Heavenly Delight</div></div><div class="content">\n  <div class="grid">\n    <div class="box"><h2>Invoice</h2><p><strong>${esc(invoiceNumber)}</strong></p><p class="muted">${esc(date)}</p></div>\n    <div class="box"><h2>Customer</h2><p><strong>${esc(customer.name)}</strong></p><p>${esc(customer.phone)}</p>\n    <p>${esc(customer.email)}</p><p class="muted">${esc(customer.address)}, ${esc(customer.city)}, ${esc(customer.state)} - ${esc(customer.pincode)}</p></div>\n  </div>\n  <table><thead><tr><th>Item</th><th class="right">Price</th><th class="right">Savings</th></tr></thead>\n  <tbody>${rows}</tbody><tfoot><tr><td class="total">Total</td><td class="right total">${money(total)}</td><td></td></tr></tfoot></table>\n  </div></div></body></html>`;\n\n  const popup = window.open("", "_blank", "width=1000,height=900");\n  if (!popup) throw new Error("Invoice window was blocked. Please allow popups for this website.");\n  popup.document.open();\n  popup.document.write(html);\n  popup.document.close();\n  popup.focus();\n}\n'

def backup(path: Path):
    if path.exists():
        target = BACKUP / path.relative_to(ROOT)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)
        print("Backup:", target)

def main():
    if not CHECKOUT.exists():
        raise SystemExit(f"ERROR: Checkout file not found: {CHECKOUT}")

    backup(CHECKOUT)
    backup(INVOICE)

    INVOICE.parent.mkdir(parents=True, exist_ok=True)
    INVOICE.write_text(INVOICE_CONTENT, encoding="utf-8")
    CHECKOUT.write_text(CHECKOUT_CONTENT, encoding="utf-8")

    print("")
    print("CUSTOMER + INVOICE CHECKOUT INSTALLED")
    print("Checkout:", CHECKOUT)
    print("Invoice utility:", INVOICE)
    print("Backup:", BACKUP)
    print("")
    print("Flow: Cart -> Checkout -> Customer Details -> Invoice -> WhatsApp")
    print("")
    print("IMPORTANT: Invoice opens in a new window.")
    print("Click 'Print / Save as PDF' to save the invoice as PDF.")
    print("Backend/database was intentionally NOT changed.")
    print("")
    print("Run: npm run build")

if __name__ == "__main__":
    main()
